const weather = $json;
const eventStart = new Date($('Extract Lat/Lng').item.json.event_start);
const eventEnd = new Date($('Extract Lat/Lng').item.json.event_end);

// Handle API error
if (!weather.hourly || weather.error || weather.cod) {
  return { json: {
    error: true,
    weather_worst: 'unavailable',
    clothing_advice: 'Weather data unavailable — dress for current conditions',
    dangerous_conditions: []
  }};
}

// Filter hourly data to event window (including 1 hour before for commute)
const startUnix = Math.floor(eventStart.getTime() / 1000) - 3600; // 1 hour before
const endUnix = Math.floor(eventEnd.getTime() / 1000);
const relevant = weather.hourly.filter(h => h.dt >= startUnix && h.dt <= endUnix);

if (relevant.length === 0) {
  return { json: {
    error: false,
    weather_worst: 'no forecast data for this window',
    clothing_advice: 'No weather data for event window',
    dangerous_conditions: []
  }};
}

// Find worst conditions
const minTemp = Math.min(...relevant.map(h => h.temp));
const maxTemp = Math.max(...relevant.map(h => h.temp));
const maxPrecip = Math.max(...relevant.map(h => (h.rain?.['1h'] || 0) + (h.snow?.['1h'] || 0)));
const maxWind = Math.max(...relevant.map(h => h.wind_speed));
const maxPop = Math.max(...relevant.map(h => h.pop || 0));

// Weather descriptions
const descriptions = relevant.flatMap(h => h.weather.map(w => w.main));
const uniqueDescs = [...new Set(descriptions)];
const weatherWorst = uniqueDescs.join(', ') + ` (${Math.round(minTemp)}°-${Math.round(maxTemp)}°C)`;

// Build clothing advice
const advice = [];

if (maxTemp > 30) advice.push('Light, breathable clothing');
else if (maxTemp > 20) advice.push('Light layers');
else if (maxTemp > 10) advice.push('Jacket recommended');
else if (maxTemp > 0) advice.push('Warm coat, layers');
else advice.push('Heavy winter coat, warm layers');

if (maxPop > 0.5 || maxPrecip > 0) advice.push('Bring umbrella');
if (maxWind > 10) advice.push('Windbreaker recommended'); // 10 m/s ≈ 36 km/h
if (minTemp < 5) advice.push('Gloves and scarf');

// Check for extreme weather
const dangerous = [];
if (minTemp >= 0 && minTemp <= 2 && maxPrecip > 0) dangerous.push('Ice risk — walk carefully');
if (maxPrecip > 5 && minTemp < 1) dangerous.push('Heavy snow expected');
if (maxWind > 19.4) dangerous.push('Extreme wind (>70 km/h) — consider postponing'); // 19.4 m/s
if (maxTemp > 38) dangerous.push('Extreme heat — stay hydrated');

return { json: {
  error: false,
  weather_worst: weatherWorst,
  clothing_advice: advice.join('. '),
  dangerous_conditions: dangerous,
  min_temp: Math.round(minTemp),
  max_temp: Math.round(maxTemp),
  max_precip_mm: maxPrecip,
  max_wind_ms: maxWind
}};
